/**
 * ChoixColonnes — the « visible columns » chooser of a registry screen: a HeroUI
 * Popover of Checkboxes. AG Grid Community exposes the hiding API
 * (`setColumnsVisible`) but its ready-made chooser belongs to the enterprise
 * edition, so this is the one piece of grid UI the blocks write.
 *
 * The list height is bounded by the viewport (`max-h-[60vh]`), never a pixel
 * constant: a fixed height overflows a short window and makes the first and last
 * columns unreachable.
 */
import { Button, Checkbox, Popover } from "@heroui/react";
import { useState } from "react";
import { type ColonneChoisie, type EtatVisibilite, estVisible } from "./colonnes.js";

export interface ChoixColonnesLabels {
  /** The trigger's text, given the number of hidden columns (derived each render). */
  columnsButton: (hiddenCount: number) => string;
  /** Accessible name of the checkbox group. */
  columnsGroupAriaLabel: string;
}

export interface ChoixColonnesProps {
  colonnes: readonly ColonneChoisie[];
  visibilite: EtatVisibilite;
  onBasculer: (champ: string) => void;
  labels: ChoixColonnesLabels;
  /** Display transform of a column label (casing); identity when omitted. */
  formatLibelle?: (libelle: string) => string;
  /** For layout tests only: render the chooser already open. */
  ouvertParDefaut?: boolean;
}

// allow-undeclared-theme-token: `default` is a HeroUI theme token; these blocks require @heroui/react and its styles.
const OPTION_CLASS =
  "flex cursor-pointer items-center gap-2 rounded px-2 py-1.5 text-sm hover:bg-default";

export function ChoixColonnes({
  colonnes,
  visibilite,
  onBasculer,
  labels,
  formatLibelle = (libelle) => libelle,
  ouvertParDefaut = false,
}: ChoixColonnesProps) {
  const [ouvert, setOuvert] = useState(ouvertParDefaut);

  // Derived from the state every render, never kept apart: a separately
  // maintained counter ends up lying.
  const nbMasquees = colonnes.filter((c) => !estVisible(visibilite, c.champ)).length;

  return (
    <Popover isOpen={ouvert} onOpenChange={setOuvert}>
      <Button variant="outline" size="sm">
        {labels.columnsButton(nbMasquees)}
      </Button>
      <Popover.Content placement="bottom">
        <Popover.Dialog>
          <fieldset
            aria-label={labels.columnsGroupAriaLabel}
            className="z-50 max-h-[60vh] w-72 overflow-y-auto border-0 p-1"
          >
            {colonnes.map((c) => (
              <Checkbox
                key={c.champ}
                isSelected={estVisible(visibilite, c.champ)}
                onChange={() => onBasculer(c.champ)}
              >
                <Checkbox.Content className={OPTION_CLASS}>
                  <Checkbox.Control>
                    <Checkbox.Indicator />
                  </Checkbox.Control>
                  <span className="w-4 tabular-nums text-muted-foreground">{c.lettre}</span>
                  <span>{formatLibelle(c.libelle)}</span>
                </Checkbox.Content>
              </Checkbox>
            ))}
          </fieldset>
        </Popover.Dialog>
      </Popover.Content>
    </Popover>
  );
}

/**
 * GrilleRegistre — the shared AG Grid of a registry screen: AG Grid Community, a
 * stable row identity, and every column sortable, filterable (with a floating
 * filter) and resizable.
 *
 * THIS MODULE DECIDES NOTHING ABOUT COLUMNS. The caller passes its own
 * `columnDefs`. The grid-level behaviours a registry screen may need — in-grid
 * edit, a selected-row style, cell tooltips — are forwarded as optional props,
 * never wired in here.
 */
import type {
  CellClickedEvent,
  CellValueChangedEvent,
  ColDef,
  GridReadyEvent,
  GridSizeChangedEvent,
  RowClassParams,
  RowStyle,
  Theme,
} from "ag-grid-community";
import { AllCommunityModule, ModuleRegistry } from "ag-grid-community";
import { AgGridReact } from "ag-grid-react";
import { fitGridWidthStrategy, registreGridTheme } from "./grid-theme.js";

// Registered on first render, not at import: a host importing the package
// without rendering a grid gets no global AG Grid side effect.
let modulesRegistered = false;
function ensureModules(): void {
  if (modulesRegistered) return;
  ModuleRegistry.registerModules([AllCommunityModule]);
  modulesRegistered = true;
}

/** Every column sorts, filters (with a floating filter) and resizes. */
const DEFAUTS: ColDef = {
  resizable: true,
  sortable: true,
  filter: true,
  floatingFilter: true,
};

export interface GrilleRegistreProps<T> {
  lignes: readonly T[];
  columnDefs: readonly ColDef<T>[];
  /** Stable row identity: a correction after a sort reaches its row. */
  getRowId: (ligne: T) => string;
  /** Global search, applied by the grid across every visible column. */
  filtreGlobal?: string;
  /** AG Grid theme; defaults to `registreGridTheme` (HeroUI variables). */
  theme?: Theme;
  onGridReady?: (e: GridReadyEvent<T>) => void;
  /** Fired when a grid cell has just been validated (in-grid edit). */
  onCelluleEditee?: (e: CellValueChangedEvent<T>) => void;
  /** Per-row style, e.g. the selected-row highlight. */
  getRowStyle?: (p: RowClassParams<T>) => RowStyle | undefined;
  /** ms before a cell tooltip shows; set when columns carry tooltips. */
  tooltipShowDelay?: number;
  /** false lets a cell take keyboard focus (needed for in-grid edit). */
  suppressCellFocus?: boolean;
  /** A cell click, e.g. to open a row's detail panel. */
  onCellClicked?: (e: CellClickedEvent<T>) => void;
  /** Fixed row height; set when a cell carries a tall control (a row action). */
  rowHeight?: number;
  /** AG Grid layout; `"autoHeight"` grows the grid to its rows (no inner scroll). */
  domLayout?: "normal" | "autoHeight" | "print";
  /** Refit columns on a size change — `refitColumns` on an autoHeight grid. */
  onGridSizeChanged?: (e: GridSizeChangedEvent<T>) => void;
}

export function GrilleRegistre<T>({
  lignes,
  columnDefs,
  getRowId,
  filtreGlobal,
  theme = registreGridTheme,
  onGridReady,
  onCelluleEditee,
  getRowStyle,
  tooltipShowDelay,
  suppressCellFocus,
  onCellClicked,
  rowHeight,
  domLayout,
  onGridSizeChanged,
}: GrilleRegistreProps<T>) {
  ensureModules();
  // The parent sets the height unless the caller asks for autoHeight.
  return (
    <div className="isolate h-full min-h-0 w-full">
      <AgGridReact<T>
        theme={theme}
        autoSizeStrategy={fitGridWidthStrategy}
        rowData={lignes as T[]}
        columnDefs={columnDefs as ColDef<T>[]}
        defaultColDef={DEFAUTS}
        quickFilterText={filtreGlobal}
        getRowId={(p) => getRowId(p.data)}
        onGridReady={onGridReady}
        onCellValueChanged={onCelluleEditee}
        onCellClicked={onCellClicked}
        getRowStyle={getRowStyle}
        tooltipShowDelay={tooltipShowDelay}
        suppressCellFocus={suppressCellFocus}
        rowHeight={rowHeight}
        domLayout={domLayout}
        onGridSizeChanged={onGridSizeChanged}
        animateRows
      />
    </div>
  );
}

/**
 * PanneauRegistreShell — the ONE drawer shell every registry screen's side panel
 * mounts. It owns the HeroUI Drawer, the left-edge resize handle, the
 * ArrowUp/ArrowDown row navigation, the header band and the prev/next footer.
 * The body is supplied as `children`: the mounting screen puts the ROW'S FIELDS
 * FIRST there.
 *
 * Why one shell: two separately written panels drift apart on the frame, and a
 * panel that mounts a tall control first pushes every field below the fold. With
 * one shell, a new registry panel cannot diverge on the frame.
 *
 * `Drawer.Content`'s published props carry no `style` slot, so the resizable
 * width rides a CSS variable on a scoped class. `forceWidthRatio` lets a screen
 * momentarily override the width (e.g. a compare mode) without owning the
 * resize state itself.
 */
import { Button, Drawer } from "@heroui/react";
import { ChevronDown, ChevronUp } from "lucide-react";
import {
  type ReactNode,
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { isEditableTarget } from "@/components/ui/row-navigation";

const DEFAULT_WIDTH_RATIO = 0.45;
const MIN_WIDTH_PX = 360;
const MAX_WIDTH_RATIO = 0.9;

// Not user-facing text. Kept as an object-literal constant with the marker BETWEEN
// properties: esbuild strips a statement-level `//` comment, never this one.
const CSS_RULES = {
  // allow-hardcoded-word: a CSS rule (the scoped width variable), not user-facing text
  width: (px: number) => `.panneau-registre-shell { --panneau-registre-width: ${px}px; }`,
};

export interface PanneauRegistreShellLabels {
  /** Accessible name of the left-edge resize handle. */
  resizeHandle: string;
  /** Accessible name of the close trigger. */
  close: string;
  previousRow: string;
  nextRow: string;
}

export interface PanneauRegistreShellProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  labels: PanneauRegistreShellLabels;
  /** The dialog's accessible name. */
  ariaLabel?: string;
  /** The header line naming the row in words. */
  contexte: string;
  /** Optional header controls (e.g. a compare toggle), left of the close trigger. */
  headerActions?: ReactNode;
  /** When set, overrides the resizable width for the duration (e.g. a compare mode). */
  forceWidthRatio?: number | null;
  onPrev: () => void;
  onNext: () => void;
  prevDisabled: boolean;
  nextDisabled: boolean;
  /** The panel body. The mounting screen puts the ROW'S FIELDS FIRST here. */
  children: ReactNode;
}

export function PanneauRegistreShell({
  open,
  onOpenChange,
  labels,
  ariaLabel,
  contexte,
  headerActions,
  forceWidthRatio = null,
  onPrev,
  onNext,
  prevDisabled,
  nextDisabled,
  children,
}: PanneauRegistreShellProps) {
  // null until measured on the client.
  const [widthPx, setWidthPx] = useState<number | null>(null);
  const dragStart = useRef<{ x: number; width: number } | null>(null);

  useEffect(() => {
    if (widthPx !== null || typeof window === "undefined") return;
    setWidthPx(Math.round(window.innerWidth * DEFAULT_WIDTH_RATIO));
  }, [widthPx]);

  const onPointerMove = useCallback((e: PointerEvent) => {
    const drag = dragStart.current;
    if (!drag) return;
    // Handle sits on the panel's LEFT edge: dragging left grows the panel.
    const dx = drag.x - e.clientX;
    const maxWidth = window.innerWidth * MAX_WIDTH_RATIO;
    setWidthPx(Math.min(maxWidth, Math.max(MIN_WIDTH_PX, drag.width + dx)));
  }, []);

  const onPointerUp = useCallback(() => {
    dragStart.current = null;
    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("pointerup", onPointerUp);
  }, [onPointerMove]);

  const onHandlePointerDown = useCallback(
    (e: ReactPointerEvent<HTMLButtonElement>) => {
      dragStart.current = {
        x: e.clientX,
        width: widthPx ?? Math.round(window.innerWidth * DEFAULT_WIDTH_RATIO),
      };
      window.addEventListener("pointermove", onPointerMove);
      window.addEventListener("pointerup", onPointerUp);
    },
    [widthPx, onPointerMove, onPointerUp],
  );

  useEffect(() => () => onPointerUp(), [onPointerUp]);

  // ArrowUp/ArrowDown move to the neighbour row without closing the panel.
  useEffect(() => {
    if (!open) return;
    function onKeyDown(e: KeyboardEvent) {
      if (isEditableTarget(e.target)) return;
      if (e.key === "ArrowUp" && !prevDisabled) {
        e.preventDefault();
        onPrev();
      } else if (e.key === "ArrowDown" && !nextDisabled) {
        e.preventDefault();
        onNext();
      }
    }
    // Capture phase: the drawer stops arrow keys from its own buttons before they bubble to window.
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, [open, prevDisabled, nextDisabled, onPrev, onNext]);

  const resolvedWidth =
    forceWidthRatio !== null && typeof window !== "undefined"
      ? Math.round(window.innerWidth * forceWidthRatio)
      : (widthPx ?? MIN_WIDTH_PX);

  const widthRule = CSS_RULES.width(resolvedWidth);

  return (
    <Drawer isOpen={open} onOpenChange={onOpenChange}>
      <Drawer.Backdrop>
        <Drawer.Content placement="right">
          <style>{widthRule}</style>
          <Drawer.Dialog
            aria-label={ariaLabel}
            className="panneau-registre-shell relative flex h-full w-full! flex-col overflow-hidden sm:w-[var(--panneau-registre-width)]! sm:min-w-[360px]! sm:max-w-[90vw]!"
          >
            <button
              type="button"
              aria-label={labels.resizeHandle}
              className="absolute inset-y-0 left-0 hidden w-1.5 cursor-col-resize touch-none bg-transparent hover:bg-border sm:block"
              onPointerDown={onHandlePointerDown}
            />
            <Drawer.Header className="flex shrink-0 flex-row items-center justify-between gap-3">
              <p className="min-w-0 truncate text-sm text-muted-foreground">{contexte}</p>
              <div className="flex shrink-0 flex-row items-center gap-2">
                {headerActions}
                <Drawer.CloseTrigger aria-label={labels.close} />
              </div>
            </Drawer.Header>
            {children}
            <Drawer.Footer className="flex shrink-0 flex-row items-center justify-end gap-2">
              <Button
                variant="outline"
                size="sm"
                isIconOnly
                aria-label={labels.previousRow}
                isDisabled={prevDisabled}
                onPress={onPrev}
              >
                <ChevronUp className="h-4 w-4" aria-hidden="true" />
              </Button>
              <Button
                variant="outline"
                size="sm"
                isIconOnly
                aria-label={labels.nextRow}
                isDisabled={nextDisabled}
                onPress={onNext}
              >
                <ChevronDown className="h-4 w-4" aria-hidden="true" />
              </Button>
            </Drawer.Footer>
          </Drawer.Dialog>
        </Drawer.Content>
      </Drawer.Backdrop>
    </Drawer>
  );
}

/**
 * RegistreEcran — the shared chrome of a registry screen: the fullscreen section
 * wrapper, the Escape / body-scroll-lock behaviour, and the toolbar scaffold — a
 * global search, the column chooser and the fullscreen toggle.
 *
 * It OWNS the fullscreen state (the one behaviour every registry screen wants
 * identically) and leaves the data region to `children`: a screen keeps its own
 * loading / empty / error states and its own grid (GrilleRegistre) beneath the
 * toolbar. Search and column visibility are CONTROLLED by the host, so a host
 * can keep them above a period selector and a period change resets neither.
 */
import { Button, SearchField, Toolbar } from "@heroui/react";
import { Maximize2, Minimize2 } from "lucide-react";
import { type ReactNode, useEffect, useState } from "react";
import { ChoixColonnes, type ChoixColonnesLabels } from "./ChoixColonnes.js";
import type { ColonneChoisie, EtatVisibilite } from "./colonnes.js";

export interface RegistreEcranLabels extends ChoixColonnesLabels {
  searchPlaceholder: string;
  searchAriaLabel: string;
  enterFullscreen: string;
  exitFullscreen: string;
}

export interface RegistreEcranProps {
  /** Section landmark label. */
  ariaLabel: string;
  labels: RegistreEcranLabels;
  /** The columns the chooser offers. */
  colonnes: readonly ColonneChoisie[];
  visibilite: EtatVisibilite;
  onBasculerColonne: (champ: string) => void;
  /** Display transform of a column label in the chooser; identity when omitted. */
  formatLibelleColonne?: (libelle: string) => string;
  /** Global search text, owned by the host. */
  filtreGlobal: string;
  onFiltreGlobalChange: (valeur: string) => void;
  /** Rendered at the start of the toolbar (e.g. a period selector). */
  avantRecherche?: ReactNode;
  /** Rendered after the chooser, before the fullscreen toggle (e.g. « add »). */
  actionsToolbar?: ReactNode;
  /** The data region: the screen's loading / empty / error states and grid. */
  children: ReactNode;
}

// Not user-facing text. Kept as an object-literal constant with the marker BETWEEN
// properties: esbuild strips a statement-level `//` comment, never this one.
const CSS_SELECTORS = {
  // allow-hardcoded-word: a CSS attribute selector (HeroUI data-slot names), not user-facing text
  openOverlay: "[data-slot=select-popover], [data-slot=popover-dialog]",
};

export function RegistreEcran({
  ariaLabel,
  labels,
  colonnes,
  visibilite,
  onBasculerColonne,
  formatLibelleColonne,
  filtreGlobal,
  onFiltreGlobalChange,
  avantRecherche,
  actionsToolbar,
  children,
}: RegistreEcranProps) {
  const [fullScreen, setFullScreen] = useState(false);

  // Escape leaves fullscreen and the page behind must not scroll; an open HeroUI
  // overlay (a select list, a popover) takes Escape first.
  useEffect(() => {
    if (!fullScreen) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (document.querySelector(CSS_SELECTORS.openOverlay)) return;
      if (e.key === "Escape") setFullScreen(false);
    };
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = previousOverflow;
    };
  }, [fullScreen]);

  return (
    <section
      aria-label={ariaLabel}
      data-fullscreen={fullScreen ? "true" : undefined}
      // Same element in both modes so the grid keeps its sort, filters and scroll.
      className={
        fullScreen
          ? "fixed inset-0 z-40 flex flex-col gap-4 bg-background p-4"
          : // Phones let the page scroll so content above cannot squeeze the grid to nothing.
            "flex min-h-[70vh] flex-1 flex-col gap-4 sm:min-h-0"
      }
    >
      <div className="shrink-0">
        <Toolbar className="flex flex-wrap items-center gap-2">
          {avantRecherche}
          <SearchField
            value={filtreGlobal}
            onChange={onFiltreGlobalChange}
            aria-label={labels.searchAriaLabel}
            className="w-full sm:w-auto"
          >
            <SearchField.Group className="h-10 min-w-64">
              <SearchField.SearchIcon />
              {/* text-base on mobile avoids iOS Safari zoom-on-focus under 16px */}
              <SearchField.Input
                placeholder={labels.searchPlaceholder}
                className="text-base sm:text-sm"
              />
              <SearchField.ClearButton />
            </SearchField.Group>
          </SearchField>
          <ChoixColonnes
            colonnes={colonnes}
            visibilite={visibilite}
            onBasculer={onBasculerColonne}
            labels={labels}
            formatLibelle={formatLibelleColonne}
          />
          {actionsToolbar}
          <Button
            variant="outline"
            size="sm"
            aria-pressed={fullScreen}
            onPress={() => setFullScreen((f) => !f)}
          >
            {fullScreen ? (
              <Minimize2 aria-hidden className="size-4" />
            ) : (
              <Maximize2 aria-hidden className="size-4" />
            )}
            {fullScreen ? labels.exitFullscreen : labels.enterFullscreen}
          </Button>
        </Toolbar>
      </div>

      {children}
    </section>
  );
}

/**
 * RegistreLigneDetail — the per-field detail of one registry row, driven by the
 * column declaration (ColonneRegistre).
 *
 * A field declared `editable` carries a pencil; a non-editable field reads the
 * host's « computed » label; a corrected field shows the host's correction line
 * (who, when, previous value). The edit is one path — `onSaveField(champ, saisie)`
 * — the same the grid cell uses. A number is edited with the host's decimal
 * separator, the format the host's validator parses.
 */
import { Pencil } from "lucide-react";
import { type FormEvent, type KeyboardEvent, useState } from "react";
import type { ColonneRegistre } from "./colonnes.js";

/** The correction trace a row carries per field. */
export interface CorrectionChamp {
  par: string;
  leMs: number;
  valeurAvant: string | number | null;
}

export interface RegistreLigneDetailLabels {
  /** Accessible name of a field's pencil button. */
  edit: (libelle: string) => string;
  /** Accessible name of a field's editor input. */
  fieldInput: (colonne: ColonneRegistre) => string;
  /** Shown on a non-editable field. */
  computed: string;
  save: string;
  cancel: string;
  /** The correction line of a corrected field (the host formats the date and an empty value). */
  correction: (correction: CorrectionChamp) => string;
}

export interface RegistreLigneDetailProps {
  colonnes: readonly ColonneRegistre[];
  /** The row, read generically by field key. */
  ligne: Readonly<Record<string, string | number | null>>;
  /** Per-field correction trace, keyed by `champ`. */
  corrections?: Readonly<Record<string, CorrectionChamp | undefined>>;
  labels: RegistreLigneDetailLabels;
  /** Renders a `montant` field. */
  formatMontant: (value: number) => string;
  /** Renders a `nombre` or `entier` field. */
  formatNombre: (value: number) => string;
  /** The decimal separator a number is edited with. */
  decimalSeparator: string;
  onSaveField: (champ: string, saisie: string) => Promise<boolean>;
}

function editValue(value: string | number | null, decimalSeparator: string): string {
  if (value == null) return "";
  return typeof value === "number" ? String(value).replace(".", decimalSeparator) : value;
}

function FieldEditor({
  col,
  initial,
  labels,
  onSave,
  onCancel,
}: {
  col: ColonneRegistre;
  initial: string;
  labels: RegistreLigneDetailLabels;
  onSave: (saisie: string) => Promise<void>;
  onCancel: () => void;
}) {
  const [draft, setDraft] = useState(initial);
  const [saving, setSaving] = useState(false);
  const inputId = `registre-field-${col.champ}`;
  const label = labels.fieldInput(col);

  async function submit(e: FormEvent) {
    e.preventDefault();
    setSaving(true);
    await onSave(draft);
    setSaving(false);
  }

  function onKeyDown(e: KeyboardEvent) {
    if (e.key === "Escape") {
      e.stopPropagation();
      onCancel();
    }
  }

  const inputClass =
    "h-8 min-w-0 flex-1 rounded-md border border-border bg-background px-2 text-base sm:text-sm";

  return (
    <form onSubmit={submit} onKeyDown={onKeyDown} className="flex flex-wrap items-center gap-2">
      {col.valeurs ? (
        <select
          id={inputId}
          aria-label={label}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          className={inputClass}
        >
          <option value="">—</option>
          {col.valeurs.map((v) => (
            <option key={v} value={v}>
              {v}
            </option>
          ))}
        </select>
      ) : (
        <input
          id={inputId}
          aria-label={label}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          // biome-ignore lint/a11y/noAutofocus: the field was opened on purpose by the pencil
          autoFocus
          className={inputClass}
        />
      )}
      <button
        type="submit"
        disabled={saving}
        className="h-8 rounded-md bg-primary px-3 text-sm text-primary-foreground disabled:opacity-50"
      >
        {labels.save}
      </button>
      <button
        type="button"
        onClick={onCancel}
        className="h-8 rounded-md border border-border px-3 text-sm"
      >
        {labels.cancel}
      </button>
    </form>
  );
}

// allow-undeclared-theme-token: `default` is a HeroUI theme token; these blocks require @heroui/react and its styles.
const PENCIL_CLASS =
  "inline-flex size-7 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-default hover:text-foreground";

export function RegistreLigneDetail({
  colonnes,
  ligne,
  corrections,
  labels,
  formatMontant,
  formatNombre,
  decimalSeparator,
  onSaveField,
}: RegistreLigneDetailProps) {
  const [editing, setEditing] = useState<string | null>(null);

  function displayValue(col: ColonneRegistre, value: string | number | null): string {
    if (value == null || value === "") return "";
    if (col.type === "montant") return formatMontant(Number(value));
    if (col.type === "nombre" || col.type === "entier") return formatNombre(Number(value));
    return String(value);
  }

  return (
    <dl className="divide-y divide-border rounded-md border border-border">
      {colonnes.map((col) => {
        const value = ligne[col.champ] ?? null;
        const correction = corrections?.[col.champ];
        return (
          <div
            key={col.champ}
            data-field={col.champ}
            className={`grid gap-1 px-3 py-2 sm:grid-cols-[11rem_1fr] sm:gap-3 ${correction ? "bg-amber-50 dark:bg-amber-950/30" : ""}`}
          >
            <dt className="text-muted-foreground">
              {col.libelle} <span className="text-xs">· {col.lettre}</span>
            </dt>
            <dd className="flex min-w-0 flex-col gap-1">
              {editing === col.champ ? (
                <FieldEditor
                  col={col}
                  initial={editValue(value, decimalSeparator)}
                  labels={labels}
                  onCancel={() => setEditing(null)}
                  onSave={async (saisie) => {
                    if (await onSaveField(col.champ, saisie)) setEditing(null);
                  }}
                />
              ) : (
                <div className="flex items-center justify-between gap-2">
                  <span className="min-w-0 break-words tabular-nums">
                    {displayValue(col, value)}
                  </span>
                  {col.editable ? (
                    <button
                      type="button"
                      aria-label={labels.edit(col.libelle)}
                      onClick={() => setEditing(col.champ)}
                      className={PENCIL_CLASS}
                    >
                      <Pencil className="size-3.5" aria-hidden="true" />
                    </button>
                  ) : (
                    <span className="shrink-0 text-xs text-muted-foreground">
                      {labels.computed}
                    </span>
                  )}
                </div>
              )}
              {correction && (
                <p className="text-xs text-amber-800 dark:text-amber-300">
                  {labels.correction(correction)}
                </p>
              )}
            </dd>
          </div>
        );
      })}
    </dl>
  );
}

/**
 * The column/field declaration a registry screen supplies. It is DATA, never a
 * code branch: the grid, the column chooser and the per-field edit all read it,
 * so a new registry screen declares its columns without touching a component.
 */
export type TypeColonneRegistre = "texte" | "nombre" | "entier" | "montant";

export interface ColonneRegistre {
  /** The key of the field on the row (technical identity). */
  champ: string;
  /** The source column letter, shown in the chooser and the panel. */
  lettre: string;
  /** The displayed label. */
  libelle: string;
  /** Drives formatting: the panel renders a number per this type. */
  type: TypeColonneRegistre;
  /** true = pencil + edit; false = the host's « computed » label. */
  editable: boolean;
  /** Optional closed set of a choice field, rendered as a menu. */
  valeurs?: readonly string[];
  /** Optional minimum width hint for the grid column. */
  largeurMin?: number;
}

/** The columns a chooser offers: only identity and label are needed. */
export interface ColonneChoisie {
  champ: string;
  lettre: string;
  libelle: string;
}

/** Which columns the user wants to see. true = visible; an absent field reads as visible. */
export type EtatVisibilite = Readonly<Record<string, boolean>>;

export function estVisible(etat: EtatVisibilite, champ: string): boolean {
  return etat[champ] !== false;
}

/**
 * The default AG Grid theme of a registry grid (GrilleRegistre), on AG Grid's
 * Theming API (no `ag-theme-*` class). Every colour is a HeroUI theme variable:
 * the registry blocks are built on HeroUI, so a host rendering them already
 * ships those variables. A host with its own brand passes its own theme through
 * GrilleRegistre's `theme` prop instead.
 */
import type { SizeColumnsToFitGridStrategy } from "ag-grid-community";
import { themeQuartz } from "ag-grid-community";

export const registreGridTheme = themeQuartz.withParams({
  accentColor: "var(--accent)",
  backgroundColor: "var(--surface)",
  foregroundColor: "var(--foreground)",
  textColor: "var(--foreground)",
  borderColor: "var(--border)",
  headerBackgroundColor: "var(--surface-secondary)",
  headerTextColor: "var(--surface-secondary-foreground)",
  headerFontWeight: 600,
  fontFamily: "var(--font-sans)",
  fontSize: 14,
  headerFontSize: 13,
  rowHeight: 40,
  headerHeight: 44,
  spacing: 8,
  wrapperBorderRadius: 8,
  rowHoverColor: "var(--surface-hover)",
  // No `selectedRowBackgroundColor`: the grid does not use the native AG Grid row
  // selection. A host highlights its selected row through `getRowStyle`.
});

/** Columns fill the grid's width instead of leaving a blank strip on the right. */
export const fitGridWidthStrategy: SizeColumnsToFitGridStrategy = {
  type: "fitGridWidth",
};

/** fitGridWidth sizes once; refit whenever the grid's width changes (pass to `onGridSizeChanged`). */
export function refitColumns(e: { api: { sizeColumnsToFit: () => void } }): void {
  e.api.sizeColumnsToFit();
}
